const COLORS = ['#E40303', '#FF8C00', '#FFED00', '#008026', '#004CFF', '#732982'];
const easings = {
  linear: t => t,
  easeInQuad: t => t * t,
  easeOutQuad: t => t * (2 - t),
  easeInOutQuad: t => t < 0.5 ? 2 * t * t : -1 + (4 - 2 * t) * t,
  easeInCubic: t => t * t * t,
  easeOutCubic: t => (--t) * t * t + 1,
  easeInOutCubic: t => t < 0.5 ? 4 * t * t * t : (t - 1) * (2 * t - 2) * (2 * t - 2) + 1,
};

function setup() {
  // Calculate grid size and cell size
  gridConfig = calculateGridSize();

  // Create square canvas
  const canvasSize = max(windowWidth, windowHeight);
  createCanvas(canvasSize, canvasSize);

  // Initialize color palette
  colorPalette = COLORS.map(c => color(c));

  // Initialize cells
  cells = [];
  let letterIndex = 0;
  let colorIndex = 0;

  for (let j = 0; j < gridConfig.gridSize; j++) {
    for (let i = 0; i < gridConfig.gridSize; i++) {
      let cell = new LetterAnimation(
        gridConfig.margin + i * gridConfig.cellSize,
        gridConfig.margin + j * gridConfig.cellSize,
        gridConfig.cellSize,
        gridConfig.cellSize,
        letterIndex,
        colorIndex
      );
      cells.push(cell);
      letterIndex = (letterIndex + 1) % letters.length;
      colorIndex = (colorIndex + 1) % colorPalette.length;
    }
  }
}

function draw() {
  background(0);
  noStroke();
  cells.forEach(cell => cell.draw());
  drawGrid();
}

function drawGrid() {
  stroke(255);
  strokeWeight(gridConfig.cellSize * 0.05);
  for (let i = 0; i <= gridConfig.gridSize; i++) {
    // Vertical lines
    line(
      gridConfig.margin + i * gridConfig.cellSize,
      gridConfig.margin,
      gridConfig.margin + i * gridConfig.cellSize,
      gridConfig.margin + gridConfig.gridSize * gridConfig.cellSize
    );
    // Horizontal lines
    line(
      gridConfig.margin,
      gridConfig.margin + i * gridConfig.cellSize,
      gridConfig.margin + gridConfig.gridSize * gridConfig.cellSize,
      gridConfig.margin + i * gridConfig.cellSize
    );
  }
}

// Get available easing function names
const easingNames = Object.keys(easings);

// Calculate grid size and cell size
function calculateGridSize() {
  const targetCellSize = 120;
  const minDimension = max(windowWidth, windowHeight);
  const margin = 40;
  const availableSize = minDimension - (2 * margin);

  // Calculate how many cells would fit with target size
  const rawGridSize = Math.floor(availableSize / targetCellSize);

  // Find closest 4n+1 number
  const n = Math.round((rawGridSize - 1) / 4);
  const gridSize = 4 * n + 1;

  // Calculate actual cell size based on grid size
  const cellSize = availableSize / gridSize;

  return { gridSize, cellSize, margin };
}

let colorPalette;
let cells;
let letters = ['L', 'O', 'V', 'E'];
let gridConfig;

class LetterAnimation {
  constructor(x, y, w, h, letterIndex, colorIndex) {
    this.x = x;
    this.y = y;
    this.w = w;
    this.h = h;
    this.centerX = x + w/2;
    this.centerY = y + h/2;
    this.bgColor = colorIndex;
    this.currentColor = (colorIndex + 1) % colorPalette.length;
    this.duration = 60;
    this.restDuration = 30;
    this.transitionDuration = 60;
    this.transitionRestDuration = 2;
    this.timer = this.duration;
    this.transitionType = 0;
    this.letterIndex = letterIndex;
    this.letter = letters[this.letterIndex];
    this.state = 'animating';
    this.currentEasing = 'easeInOutCubic'; // Default easing
  }

  reset() {
    this.timer = this.duration;
    this.bgColor = this.currentColor;
    this.currentColor = (this.currentColor + 1) % colorPalette.length;
    this.state = 'animating';
    this.letterIndex = (this.letterIndex + 1) % letters.length;
    this.letter = letters[this.letterIndex];
    // Select a new random easing function
    this.currentEasing = random(easingNames);
  }

  drawLetterL(t) {
    let w = this.w * 0.6;
    push();
    translate(this.w - w, 0);
    switch(this.transitionType) {
      case 0: // Diagonal wipe
        const p = t * w;
        triangle(0, 0, p, 0, 0, p);
        triangle(w, w, w - p, w, w, w - p);
        break;
      // Add other transition types here
    }
    pop();
  }

  drawLetterO(t) {
    const p = t * TWO_PI;
    const r = this.w * 0.8;
    arc(this.w/2, this.h/2, r, r, 0, p);
  }

  drawLetterV(t) {
    triangle(0, 0, this.w/2, this.h * t, this.w, 0);
  }

  drawLetterE(t) {
    let h = this.h * 0.1;
    let h2 = (this.h - 2 * h) / 3;
    let w = this.w * 0.6;
    let w2 = this.w - w;
    push();
    translate(w, h2);
    rect(w2, 0, -t * w2, h);
    translate(0, h2);
    rect(w2, 0, -t * w2, h);
    pop();
  }

  drawLetter(t, isTransition = false) {
    if (isTransition) {
      t = 1
    }
    switch(this.letter) {
      case 'L': this.drawLetterL(t); break;
      case 'O': this.drawLetterO(t); break;
      case 'V': this.drawLetterV(t); break;
      case 'E': this.drawLetterE(t); break;
    }
  }

  drawTransitionFill(t) {
    this.drawLetter(1, true)
    switch(this.letter) {
      case 'L':
        rect(this.w, 0, -this.w * t, this.h * t) 
        break;
      case 'O':
        let diag = sqrt(this.w * this.w + this.h * this.h)
        // Mask the arc
        push()
        clip(() => {
          rect(0, 0, this.w, this.h)
        })
        arc(this.w/2, this.h/2, diag, diag, 0, t * TWO_PI)
        // circle(this.w/2, this.h/2, diag * t)
        pop()
        break;
      case 'V':
        triangle(
          0, 0,
          this.w/2, this.h,
          0, this.w * t
        )
        triangle(
          this.w, 0,
          this.w/2, this.h,
          this.w, this.w * t
        )
        break;
      case 'E':
        // lerp the two rects
        let h = this.h * 0.1
        let h2 = (this.h - 2 * h) / 3
        let w = this.w * 0.6
        let w2 = this.w - w
        let xr, yr, wr, hr
        push()
        xr = lerp(w, 0, t)
        yr = lerp(h2, 0, t)
        wr = lerp(this.w - w, this.w, t)
        hr = lerp(h, this.h / 2, t)
        rect(xr, yr, wr, hr)
        pop()

        push()
        xr = lerp(w, 0, t)
        yr = lerp(2 * h2, this.h/2, t)
        wr = lerp(this.w - w, this.w, t)
        hr = lerp(h, this.h / 2, t)
        rect(xr, yr, wr, hr)
        pop()
        break;
    }
  }

  draw() {
    // Draw background
    fill(colorPalette[this.bgColor]);
    rect(this.x, this.y, this.w, this.h);

    let t;
    if (this.state === 'animating' || this.state === 'resting') {
      if (this.state === 'animating') {
        t = map(this.timer, this.duration, 0, 0, 1);
      } else {
        t = 1;
      }
      const easedT = easings[this.currentEasing](t);

      push();
      translate(this.x, this.y);
      noStroke();
      fill(colorPalette[this.currentColor]);
      this.drawLetter(easedT);
      pop();

    } else if (this.state === 'transitioning') {
      t = map(this.timer, this.transitionDuration, 0, 0, 1);
      const easedT = easings[this.currentEasing](t);

      push();
      translate(this.x, this.y);
      noStroke();
      fill(colorPalette[this.currentColor]);
      this.drawLetter(1, true);
      this.drawTransitionFill(easedT);
      pop();

    } else if (this.state === 'transitionRest') {
      push();
      translate(this.x, this.y);
      fill(colorPalette[this.currentColor]);
      rect(0, 0, this.w, this.h);
      pop();
    }

    // Update timer and state
    this.timer--;
    if (this.timer <= 0) {
      switch(this.state) {
        case 'animating':
          this.state = 'resting';
          this.timer = this.restDuration;
          break;
        case 'resting':
          this.state = 'transitioning';
          this.timer = this.transitionDuration;
          break;
        case 'transitioning':
          this.state = 'transitionRest';
          this.timer = this.transitionRestDuration;
          break;
        case 'transitionRest':
          this.reset();
          this.state = 'animating';
          break;
      }
    }
  }
}

function windowResized() {
  // Recalculate grid size and cell size
  const oldGridSize = gridConfig.gridSize;
  gridConfig = calculateGridSize();

  // Resize canvas
  const canvasSize = max(windowWidth, windowHeight);
  resizeCanvas(canvasSize, canvasSize);

  // If grid size changed, we need to recreate all cells
  if (oldGridSize !== gridConfig.gridSize) {
    // Clear existing cells
    cells = [];
    let letterIndex = 0;
    let colorIndex = 0;

    // Create new cells with updated grid size
    for (let j = 0; j < gridConfig.gridSize; j++) {
      for (let i = 0; i < gridConfig.gridSize; i++) {
        let cell = new LetterAnimation(
          gridConfig.margin + i * gridConfig.cellSize,
          gridConfig.margin + j * gridConfig.cellSize,
          gridConfig.cellSize,
          gridConfig.cellSize,
          letterIndex,
          colorIndex
        );
        cells.push(cell);
        letterIndex = (letterIndex + 1) % letters.length;
        colorIndex = (colorIndex + 1) % colorPalette.length;
      }
    }
  } else {
    // If grid size didn't change, just update cell positions and sizes
    cells.forEach((cell, index) => {
      const i = index % gridConfig.gridSize;
      const j = Math.floor(index / gridConfig.gridSize);
      cell.x = gridConfig.margin + i * gridConfig.cellSize;
      cell.y = gridConfig.margin + j * gridConfig.cellSize;
      cell.w = gridConfig.cellSize;
      cell.h = gridConfig.cellSize;
      cell.centerX = cell.x + cell.w/2;
      cell.centerY = cell.y + cell.h/2;
    });
  }
}


